        root.getChild("Arm2").render(poses, vertices, light, overlay);
        root.getChild("Arm3").render(poses, vertices, light, overlay);
        root.getChild("Arm4").render(poses, vertices, light, overlay);
        root.getChild("Base").render(poses, vertices, light, overlay);
